import numpy as np

# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: This is a compact implementation of a randomized search algorithm for black-box optimization.
# Search state: The search state is represented by a single candidate solution.
# Candidate generation: New candidate solutions are generated by adding Gaussian noise to the current best solution.
# Selection and replacement: The new candidate solution replaces the current best solution if it has a lower objective function value.
# Adaptation: The standard deviation of the Gaussian noise is adapted based on the difference between the new and current best solutions.
# Exploration mechanisms: The Gaussian noise provides a simple exploration mechanism, with the standard deviation controlling the step size.
# Exploitation mechanisms: The algorithm focuses exploitation on the current best solution by generating new candidates around it.
# Boundary handling: Candidate solutions that violate the problem bounds are reflected back into the feasible region.
# Budget strategy: The algorithm uses the full evaluation budget, making the most of the available function evaluations.
# Closest known influences: The algorithm is similar to a basic version of Covariance Matrix Adaptation Evolution Strategy (CMA-ES), but without the more advanced covariance matrix adaptation.
# Novelty or unusual aspects: The algorithm is simple and compact, using only standard Python and NumPy functionality.
# Failure modes: The algorithm may struggle on highly multimodal or deceptive landscapes, as it does not have advanced mechanisms for escaping local optima.
# ALGORITHM_ANALYSIS_NOTE_END

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim
        self.x = np.zeros(dim)
        self.y = float('inf')
        self.sigma = 1.0

    def __call__(self, func):
        for _ in range(self.budget):
            candidate = self.x + self.sigma * np.random.normal(size=self.dim)
            candidate = np.clip(candidate, func.lower, func.upper)
            y = func(candidate)
            if y < self.y:
                self.x = candidate
                self.y = y
            self.sigma = max(0.01, self.sigma * np.exp(-0.1 * abs(y - self.y)))
        return self.x, self.y
